// 1. Critical Input Validation (Fatal Errors that Disable cannot fix via software state reset alone)
if (wa_input.requested_torque_nm == NULL || wa_input.axes == NULL) {
    wa_state.mode = WA_FAULT;
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

if (!adcs_is_finite_vec3(wa_input.requested_torque_nm)) {
    wa_state.mode = WA_FAULT;
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

// Validate Config Ranges
if (wa_config.release_cycles < 1 || wa_config.release_cycles > 20 ||
    wa_config.restore_cycles < 1 || wa_config.restore_cycles > 20) {
    wa_state.mode = WA_FAULT;
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

for (int i = 0; i < 3; ++i) {
    if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0 ||
        !isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) || wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0) {
        wa_state.mode = WA_FAULT;
        wa_output.mode = WA_FAULT;
        wa_output.wheel_torque_nm[0] = 0.0;
        wa_output.wheel_torque_nm[1] = 0.0;
        wa_output.wheel_torque_nm[2] = 0.0;
        wa_output.achieved_torque_nm.x = 0.0;
        wa_output.achieved_torque_nm.y = 0.0;
        wa_output.achieved_torque_nm.z = 0.0;
        wa_output.residual_torque_nm.x = 0.0;
        wa_output.residual_torque_nm.y = 0.0;
        wa_output.residual_torque_nm.z = 0.0;
        wa_output.residual_norm_nm = 0.0;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = 0U;
        return;
    }
}

// 2. Handle Disable: Resets to NORMAL and zeros outputs/commands
if (!wa_input.enable) {
    wa_state.mode = WA_NORMAL;
    wa_output.mode = WA_NORMAL;
    wa_output.clean_count = 0;
    wa_output.restore_count = 0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    return;
}

// 3. Validate Axes: Exactly 3, Mutually Orthogonal, Normalized
if (wa_input.axis_count != 3) {
    wa_state.mode = WA_FAULT;
    wa_output.mode = WA_FAULT;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm.x = 0.0;
    wa_output.achieved_torque_nm.y = 0.0;
    wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0;
    wa_output.residual_torque_nm.y = 0.0;
    wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    return;
}

adcs_vec3_t norm_axes[3];
for (int i = 0; i < 3; ++i) {
    if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &norm_axes[i]) != ADCS_OK) {
        wa_state.mode = WA_FAULT;
        wa_output.mode = WA_FAULT;
        wa_output.wheel_torque_nm[0] = 0.0;
        wa_output.wheel_torque_nm[1] = 0.0;
        wa_output.wheel_torque_nm[2] = 0.0;
        wa_output.achieved_torque_nm.x = 0.0;
        wa_output.achieved_torque_nm.y = 0.0;
        wa_output.achieved_torque_nm.z = 0.0;
        wa_output.residual_torque_nm.x = 0.0;
        wa_output.residual_torque_nm.y = 0.0;
        wa_output.residual_torque_nm.z = 0.0;
        wa_output.residual_norm_nm = 0.0;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = 0U;
        return;
    }
}

for (int i = 0; i < 3; ++i) {
    for (int j = i + 1; j < 3; ++j) {
        double dot = adcs_vec3_dot(&norm_axes[i], &norm_axes[j]);
        if (fabs(dot) > ADCS_EPS_COLLINEAR) {
            wa_state.mode = WA_FAULT;
            wa_output.mode = WA_FAULT;
            wa_output.wheel_torque_nm[0] = 0.0;
            wa_output.wheel_torque_nm[1] = 0.0;
            wa_output.wheel_torque_nm[2] = 0.0;
            wa_output.achieved_torque_nm.x = 0.0;
            wa_output.achieved_torque_nm.y = 0.0;
            wa_output.achieved_torque_nm.z = 0.0;
            wa_output.residual_torque_nm.x = 0.0;
            wa_output.residual_torque_nm.y = 0.0;
            wa_output.residual_torque_nm.z = 0.0;
            wa_output.residual_norm_nm = 0.0;
            wa_output.saturation_mask = 0U;
            wa_output.slew_mask = 0U;
            wa_output.unavailable_mask = 0U;
            return;
        }
    }
}

// 4. Determine Availability
unint32 avail_mask = wa_input.available_mask & 0x7;
unint32 unavailable_mask = (~avail_mask) & 0x7;
int avail_count = 0;
for (int i = 0; i < 3; ++i) {
    if ((avail_mask >> i) & 1) avail_count++;
}

// 5. Allocation & Limiting
wa_output.unavailable_mask = unavailable_mask;
wa_output.saturation_mask = 0U;
wa_output.slew_mask = 0U;

int has_saturation = 0;
int has_slew = 0;
int all_wheels_available = (avail_count == 3);

double ideal_torques[3] = {0.0};
for (int i = 0; i < 3; ++i) {
    if ((avail_mask >> i) & 1) {
        ideal_torques[i] = -adcs_vec3_dot(&norm_axes[i], wa_input.requested_torque_nm);
    } else {
        ideal_torques[i] = 0.0;
    }
}

double limited_torques[3];
for (int i = 0; i < 3; ++i) {
    if (!(avail_mask & (1 << i))) {
        limited_torques[i] = 0.0;
        continue;
    }
    double mag_limit = wa_config.wheel_limit_nm[i];
    if (fabs(ideal_torques[i]) > mag_limit) {
        limited_torques[i] = copysign(mag_limit, ideal_torques[i]);
        has_saturation = 1;
        wa_output.saturation_mask |= (1 << i);
    } else {
        limited_torques[i] = ideal_torques[i];
    }
}

double final_torques[3];
for (int i = 0; i < 3; ++i) {
    if (!(avail_mask & (1 << i))) {
        final_torques[i] = 0.0;
        continue;
    }
    double prev = wa_state.previous_wheel_torque_nm[i];
    double diff = limited_torques[i] - prev;
    double slew_limit = wa_config.max_wheel_slew_nm_per_cycle[i];

    if (fabs(diff) > slew_limit) {
        final_torques[i] = prev + copysign(slew_limit, diff);
        has_slew = 1;
        wa_output.slew_mask |= (1 << i);
    } else {
        final_torques[i] = limited_torques[i];
    }
}

for (int i = 0; i < 3; ++i) {
    wa_state.previous_wheel_torque_nm[i] = final_torques[i];
}

adcs_vec3_t achieved = {0.0, 0.0, 0.0};
for (int i = 0; i < 3; ++i) {
    if (avail_mask & (1 << i)) {
        adcs_vec3_t term = adcs_vec3_scale(&norm_axes[i], final_torques[i]);
        achieved = adcs_vec3_add(&achieved, &term);
    }
}

adcs_vec3_t residual = adcs_vec3_sub(wa_input.requested_torque_nm, &achieved);
double residual_norm = adcs_vec3_norm(&residual);

// 6. State Machine
int is_limited_event = has_saturation || has_slew;
int is_degraded_condition = !all_wheels_available;

switch (wa_state.mode) {
    case WA_FAULT:
        // Stays FAULT
        break;

    case WA_LIMITED:
        if (is_limited_event) {
            wa_output.clean_count = 0;
        } else {
            wa_output.clean_count++;
            if (wa_output.clean_count >= wa_config.release_cycles) {
                wa_state.mode = WA_NORMAL;
                wa_output.clean_count = 0;
            }
        }
        break;

    case WA_DEGRADED:
        if (is_degraded_condition) {
            // Stay degraded
        } else if (!is_limited_event) {
            wa_state.mode = WA_RECOVERING;
            wa_output.restore_count = 0;
        }
        break;

    case WA_RECOVERING:
        if (is_degraded_condition) {
            wa_state.mode = WA_DEGRADED;
            wa_output.restore_count = 0;
        } else if (is_limited_event) {
            wa_state.mode = WA_LIMITED;
            wa_output.clean_count = 0;
        } else {
            wa_output.restore_count++;
            if (wa_output.restore_count >= wa_config.restore_cycles) {
                wa_state.mode = WA_NORMAL;
                wa_output.restore_count = 0;
            }
        }
        break;

    case WA_NORMAL:
        if (is_limited_event) {
            wa_state.mode = WA_LIMITED;
            wa_output.clean_count = 0;
        } else if (is_degraded_condition) {
            wa_state.mode = WA_DEGRADED;
            wa_output.restore_count = 0;
        }
        break;

    default:
        wa_state.mode = WA_FAULT;
        break;
}

wa_output.mode = wa_state.mode;
wa_output.wheel_torque_nm[0] = final_torques[0];
wa_output.wheel_torque_nm[1] = final_torques[1];
wa_output.wheel_torque_nm[2] = final_torques[2];
wa_output.achieved_torque_nm = achieved;
wa_output.residual_torque_nm = residual;
wa_output.residual_norm_nm = residual_norm;

