    if (!(avail_mask & ((uint32_t)1 << i))) {
        final_torques[i] = 0.0;
        continue;
    }
    double prev = wa_state.previous_wheel_torque_nm[i];
    double diff = limited_torques[i] - prev;
    double slew_limit = wa_config.max_wheel_slew_nm_per_cycle[i];

    if (fabs(diff) > slew_limit) {
        final_torques[i] = prev + copysign(slew_limit, diff);
        has_slew = 1;
        wa_output.slew_mask |= ((uint32_t)1U << (uint32_t)i);
    } else {
        final_torques[i] = limited_torques[i];
