        wa_state.previous_wheel_torque_nm[i] = 0.0;
    }
    wa_output.achieved_torque_nm.x = 0.0; wa_output.achieved_torque_nm.y = 0.0; wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0; wa_output.residual_torque_nm.y = 0.0; wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    return;
}

adcs_vec3_t norm_axes[3];
int valid_axes = 1;
for (int i = 0; i < 3; i++) {
    if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &norm_axes[i]) != ADCS_OK) {
        valid_axes = 0;
        break;
    }
}
if (valid_axes) {
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            double dot = adcs_vec3_dot(&norm_axes[i], &norm_axes[j]);
            if (fabs(dot) > ADCS_EPS_COLLINEAR) {
                valid_axes = 0;
                break;
            }
        }
        if (!valid_axes) break;
    }
} else {
    /* Axes are invalid; valid_axes remains 0 */
}

int valid_config = 1;
for (int i = 0; i < 3; i++) {
    if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0 ||
        !isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) || wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0) {
        valid_config = 0;
        break;
    }
}
if (!(wa_config.release_cycles >= 1 && wa_config.release_cycles <= 20) ||
    !(wa_config.restore_cycles >= 1 && wa_config.restore_cycles <= 20)) {
    valid_config = 0;
} else {
    /* Cycles are within valid range [1, 20] */
}

if (!valid_axes || !valid_config) {
    wa_output.mode = WA_FAULT;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    for (int i = 0; i < 3; i++) {
        wa_output.wheel_torque_nm[i] = 0.0;
        wa_state.previous_wheel_torque_nm[i] = 0.0;
    }
    wa_output.achieved_torque_nm.x = 0.0; wa_output.achieved_torque_nm.y = 0.0; wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0; wa_output.residual_torque_nm.y = 0.0; wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    return;
}

if (!wa_input.enable) {
    wa_output.mode = WA_NORMAL;
    wa_output.clean_count = 0;
    wa_output.restore_count = 0;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    for (int i = 0; i < 3; i++) {
        wa_output.wheel_torque_nm[i] = 0.0;
        wa_state.previous_wheel_torque_nm[i] = 0.0;
    }
    wa_output.achieved_torque_nm.x = 0.0; wa_output.achieved_torque_nm.y = 0.0; wa_output.achieved_torque_nm.z = 0.0;
    wa_output.residual_torque_nm.x = 0.0; wa_output.residual_torque_nm.y = 0.0; wa_output.residual_torque_nm.z = 0.0;
    wa_output.residual_norm_nm = 0.0;
    return;
}

wa_output.saturation_mask = 0U;
wa_output.slew_mask = 0U;
wa_output.unavailable_mask = 0U;
wa_output.achieved_torque_nm.x = 0.0;
wa_output.achieved_torque_nm.y = 0.0;
wa_output.achieved_torque_nm.z = 0.0;

uint32_t current_unavailable_mask = 0U;
uint32_t current_saturation_mask = 0U;
uint32_t current_slew_mask = 0U;
int any_unavailable = 0;
int any_limited = 0;

for (size_t i = 0; i < 3U; i++) {
    const uint32_t bit_mask = (1U << i);
    const int is_available = ((wa_input.available_mask & bit_mask) != 0U);

    if (is_available == 0) {
        wa_output.wheel_torque_nm[i] = 0.0;
        current_unavailable_mask |= bit_mask;
        any_unavailable = 1;
        /* Update previous torque to zero for unavailable wheels to prevent slew spikes on recovery */
        wa_state.previous_wheel_torque_nm[i] = 0.0;
        continue;
    }

    /* Calculate requested torque component along this axis */
    double req_val = -(wa_input.axes[i].x * wa_input.requested_torque_nm->x +
                       wa_input.axes[i].y * wa_input.requested_torque_nm->y +
                       wa_input.axes[i].z * wa_input.requested_torque_nm->z);

    double limited_val = req_val;
    int sat_occurred = 0;
    int slew_occurred = 0;

    /* Apply magnitude limit */
    if (fabs(req_val) > wa_config.wheel_limit_nm[i]) {
        limited_val = copysign(wa_config.wheel_limit_nm[i], req_val);
        sat_occurred = 1;
    }

    /* Apply slew limit relative to previous command */
    double prev_val = wa_state.previous_wheel_torque_nm[i];
    double diff = limited_val - prev_val;
    double max_slew = wa_config.max_wheel_slew_nm_per_cycle[i];

    if (diff > max_slew) {
        limited_val = prev_val + max_slew;
        slew_occurred = 1;
    } else if (diff < -max_slew) {
        limited_val = prev_val - max_slew;
        slew_occurred = 1;
    }

    if (sat_occurred != 0) {
        current_saturation_mask |= bit_mask;
        any_limited = 1;
    }
    if (slew_occurred != 0) {
        current_slew_mask |= bit_mask;
        any_limited = 1;
    }

    wa_output.wheel_torque_nm[i] = limited_val;
    wa_state.previous_wheel_torque_nm[i] = limited_val;

    wa_output.achieved_torque_nm.x += limited_val * wa_input.axes[i].x;
    wa_output.achieved_torque_nm.y += limited_val * wa_input.axes[i].y;
    wa_output.achieved_torque_nm.z += limited_val * wa_input.axes[i].z;
}

wa_output.residual_torque_nm.x = wa_input.requested_torque_nm->x - wa_output.achieved_torque_nm.x;
wa_output.residual_torque_nm.y = wa_input.requested_torque_nm->y - wa_output.achieved_torque_nm.y;
wa_output.residual_torque_nm.z = wa_input.requested_torque_nm->z - wa_output.achieved_torque_nm.z;
wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);

/* Update masks in output */
wa_output.saturation_mask = current_saturation_mask;
wa_output.slew_mask = current_slew_mask;
wa_output.unavailable_mask = current_unavailable_mask;

int has_unavail = any_unavailable;
int has_lim = any_limited;

wa_mode_t smode = wa_state.mode;

switch (smode) {
    case WA_NORMAL:
        if (has_lim != 0) {
            smode = WA_LIMITED;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        } else if (has_unavail != 0) {
            smode = WA_DEGRADED;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        } else {
            wa_state.clean_count++;
        }
        break;

    case WA_LIMITED:
        if (has_lim != 0 || has_unavail != 0) {
            if (has_unavail != 0) {
                smode = WA_DEGRADED;
            }
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        } else {
            wa_state.clean_count++;
            if (wa_state.clean_count >= wa_config.release_cycles) {
                smode = WA_NORMAL;
                wa_state.restore_count = 0U;
            }
        }
        break;

    case WA_DEGRADED:
        if (has_unavail != 0) {
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        } else {
            smode = WA_RECOVERING;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        }
        break;

    case WA_RECOVERING:
        if (has_unavail != 0) {
            smode = WA_DEGRADED;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        } else if (has_lim != 0) {
            smode = WA_LIMITED;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        } else {
            wa_state.restore_count++;
            if (wa_state.restore_count >= wa_config.restore_cycles) {
                smode = WA_NORMAL;
                wa_state.clean_count = 0U;
            }
        }
        break;

    case WA_FAULT:
        /* In fault state, outputs are already zeroed by validation block above.
           Maintain fault state until reset or external intervention. */
        break;

    default:
        /* MISRA Rule 16.4: Default branch required.
           Transition to Fault for unknown states. */
        smode = WA_FAULT;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
        break;
}

wa_output.mode = smode;
wa_output.clean_count = wa_state.clean_count;
wa_output.restore_count = wa_state.restore_count;
